  function dissolveGroup(id){const g=project.groups.find(g=>g.id===id);if(!g)return;confirmAction('解散“'+g.name+'”','这一组会恢复为散箱，货物总数量不变。',()=>{project.groups=project.groups.filter(g=>g.id!==id);if(draft.id===id){draft={id:null,name:'新组合',allowRotate:true,children:[]};selected=null;history=[];}invalidate();stackEditing=false;renderStack();});}
