    const saved=draft.id?project.groups.find(g=>g.id===draft.id):null;const unsaved=draft.children.length&&(!saved||JSON.stringify(saved.children)!==JSON.stringify(draft.children)||saved.allowRotate!==draft.allowRotate);
    if(unsaved){dialog('叠箱草稿尚未保存','<p>当前草稿尚未保存为组合。请先保存组合，或确认按现有已保存的组合与散箱排柜。</p>',[{label:'回去保存组合',run:()=>{$('modal').close();stackEditing=true;go('stack');}},{label:'使用已保存内容排柜',primary:true,run:()=>{$('modal').close();startCalculation(action);}}]);return;}startCalculation(action);
